-- Lease tokens are never exposed by ordinary table reads, including direct REST.
revoke select on public.attempts from authenticated;
grant select(id,school_id,version_id,student_id,started_at,deadline,finalized_at,status,writer_epoch,display_order,receipt)on public.attempts to authenticated;
create function public.runtime_takeover(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;se private.sessions;m public.memberships;begin select * into se from private.sessions where token_hash=p->>'sessionHash'and revoked_at is null and expires_at>now()and reauthenticated_at>now()-interval '5 minutes';if not found then raise exception 'RECENT_REAUTH_REQUIRED'using errcode='42501';end if;select * into m from public.memberships where id=se.user_id and active and role='student';select * into a from public.attempts where id=(p->>'attemptId')::uuid and student_id=m.id for update;if not found or a.status<>'in_progress'or a.deadline<=now()or exists(select 1 from public.schools where id=a.school_id and status='suspended')then raise exception 'ATTEMPT_UNAVAILABLE';end if;update public.attempts set writer=(p->>'writer')::uuid,writer_epoch=writer_epoch+1 where id=a.id returning * into a;insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action)values(a.school_id,m.id,'student',m.id,'attempt.writer.takeover');return to_jsonb(a);end$$;
revoke execute on function public.runtime_takeover(jsonb)from public,anon,authenticated;grant execute on function public.runtime_takeover(jsonb)to service_role;
